mapper.select:
SELECT EXISTS(
    SELECT 1
    FROM generic_master asset_category_master
    INNER JOIN generic_master_values asset_category
        ON asset_category.generic_master_id = asset_category_master.id
        AND asset_category.company_id = #{companyId}
    WHERE asset_category_master.code = 'ASSET_CATEGORY'
        AND asset_category_master.is_deleted = FALSE
        AND asset_category.code = #{code}
)

mapper.update:
UPDATE generic_master_values asset_category
INNER JOIN generic_master asset_category_master
    ON asset_category_master.id = asset_category.generic_master_id
    AND asset_category_master.code = 'ASSET_CATEGORY'
    AND asset_category_master.is_deleted = FALSE
SET asset_category.is_deleted = TRUE,
    asset_category.updated_by = #{updatedBy}
WHERE asset_category.id = #{id}
    AND asset_category.company_id = #{companyId}
    AND asset_category.is_deleted = FALSE

UPDATE generic_master_values asset_category
INNER JOIN generic_master asset_category_master
    ON asset_category_master.id = asset_category.generic_master_id
    AND asset_category_master.code = 'ASSET_CATEGORY'
    AND asset_category_master.is_deleted = FALSE
SET asset_category.is_deleted = FALSE,
    asset_category.updated_by = #{updatedBy}
WHERE asset_category.id = #{id}
    AND asset_category.company_id = #{companyId}
    AND asset_category.is_deleted = TRUE
